"""Small static report; opens offline, with all scenario data embedded."""
import html,json
from pathlib import Path

def money(x):return f'{"+" if x>=0 else "−"}${abs(x):.2f}'
def chart_svg(result):
    # A small descriptive chart, with all points already computed by analysis.py.
    # Uses no smoothing, secondary axis, or hidden rescaling across scenarios.
    vals=result['event_path'];points={e:sum(r['effect'] for r in vals if r['event_week']==e)/2 for e in range(8)}
    sc=result['synthetic_control']['event_path'];sp={e:sum(r['effect'] for r in sc if r['event_week']==e)/2 for e in range(-8,8)}
    W,H=800,280;left,right,top,bottom=65,760,25,230
    X=lambda e:left+(e+8)*(right-left)/15
    Y=lambda v:bottom-(v+5)*(bottom-top)/40
    lines=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 280" role="img" aria-label="Contribution effect by week relative to launch. Synthetic control in blue; cohort DiD in orange. Synthetic observations only.">']
    lines.append('<rect width="800" height="280" fill="white"/>')
    for v in [-5,0,10,20,30,35]:
        lines.append(f'<path d="M{left},{Y(v)}H{right}" stroke="#dde4e8"/><text x="52" y="{Y(v)+4}" text-anchor="end" font-family="sans-serif" font-size="12">${v}</text>')
    lines.append(f'<path d="M{X(-.5)},{top}V{bottom}" stroke="#5d6b76" stroke-dasharray="4 4"/>')
    for e in [-8,-4,0,4,7]:lines.append(f'<text x="{X(e)}" y="252" text-anchor="middle" font-family="sans-serif" font-size="12">{e}</text>')
    for values,color in [(sp,'#166e86'),(points,'#bd5d24')]:
        xy=' '.join(f'{X(e):.2f},{Y(v):.2f}' for e,v in values.items())
        lines.append(f'<polyline points="{xy}" fill="none" stroke="{color}" stroke-width="2.5"/>')
        for e,v in values.items():lines.append(f'<circle cx="{X(e)}" cy="{Y(v)}" r="3" fill="{color}"/>')
    lines.append('<text x="400" y="276" text-anchor="middle" font-family="sans-serif" font-size="12">Weeks relative to eligibility launch</text></svg>')
    return ''.join(lines)

def render(results,out):
    charts={r['scenario']:chart_svg(r) for r in results}
    for key,svg in charts.items():(out/f'{key}.svg').write_text(svg)
    cards=[]
    for r in results:
        cards.append(f'''<section class="scenario" id="{r['scenario']}"><p class="verdict">{html.escape(r['verdict'])}</p><div class="metrics"><div>New offer revenue<strong>{money(r['new_offer_lift'])}</strong></div><div>Existing product revenue<strong>{money(r['existing_product_change'])}</strong></div><div>Business contribution<strong>{money(r['cohort_did'])}</strong></div></div><p>Per baseline-eligible customer per week. Contribution subtracts modeled service costs. These are simulated outcomes, not Intuit results.</p><div class="chart">{charts[r['scenario']]}</div><p class="legend"><span>● Synthetic control</span> <span>● Cohort DiD</span></p><table><tr><th>Check</th><th>Result</th><th>What it tells us</th></tr><tr><td>Same-market before / after</td><td>{money(r['naive_before_after'])}</td><td>Includes calendar changes; not a causal estimate.</td></tr><tr><td>Cohort DiD, 95% bootstrap interval</td><td>{money(r['cohort_did'])} [{money(r['bootstrap_95_interval'][0])}, {money(r['bootstrap_95_interval'][1])}]</td><td>Never-treated controls; eight weeks per cohort; resample whole markets.</td></tr><tr><td>Synthetic control</td><td>{money(r['synthetic_control']['estimate'])}</td><td>Nonnegative donor weights fit before launch.</td></tr><tr><td>Pre-launch gap slope</td><td>${r['pretrend_slope']:.3f} / week</td><td>Warning above $0.15; this threshold is a demo choice, not a hypothesis test.</td></tr><tr><td>False launch eight weeks early</td><td>{money(r['false_launch_placebo'])}</td><td>Warning above $0.75 in absolute value.</td></tr><tr><td>Held-out synthetic-control error</td><td>${r['synthetic_control']['max_validation_rmse']:.2f}</td><td>Maximum cohort pre-launch validation RMSE; warning above $1.</td></tr><tr><td>Known simulation truth</td><td>{money(r['simulated_truth'])}</td><td>Used to check the estimator only; never used to fit it.</td></tr></table></section>''')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Did it grow?</title><style>*{box-sizing:border-box}body{font:16px/1.6 system-ui,sans-serif;color:#1c2c36;background:#f5f5f0;margin:0}main{max-width:1000px;margin:auto;padding:45px 28px}h1{font-size:clamp(44px,7vw,76px);line-height:1.05;letter-spacing:-3px;margin:14px 0 18px}h2{font-size:23px}p{max-width:780px}.eyebrow{font:12px ui-monospace,monospace;letter-spacing:1px;text-transform:uppercase;color:#52616b}.intro{font-size:22px;max-width:700px}.notice{font-size:14px;border-top:1px solid #b6c2c9;padding-top:16px}nav{display:flex;gap:9px;flex-wrap:wrap;margin:30px 0}button{font:inherit;border:1px solid #8b9da7;border-radius:4px;background:transparent;padding:10px 15px;cursor:pointer}button[aria-pressed=true]{background:#183e4d;color:white;border-color:#183e4d}.scenario{display:none}.scenario.active{display:block}.verdict{font-weight:700;font-size:21px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;border-top:1px solid #aab9bf;border-bottom:1px solid #aab9bf;padding:22px 0}.metrics strong{display:block;font-size:36px;font-weight:600;letter-spacing:-1px}.metrics div{font-size:14px}.chart{background:white;padding:12px;margin-top:26px}.chart svg{width:100%;height:auto}.legend{font-size:13px}.legend span:first-child{color:#166e86}.legend span:last-child{color:#bd5d24;margin-left:16px}table{border-collapse:collapse;width:100%;font-size:13px;margin:24px 0}td,th{text-align:left;padding:12px 10px;border-bottom:1px solid #cbd4d8}td:nth-child(2){white-space:nowrap;font-variant-numeric:tabular-nums}.sensitivity{background:#e5edf0;padding:22px;margin:30px 0}input{width:100%;max-width:500px;display:block;margin:16px 0}output{font-weight:700}a{color:#166e86}footer{font-size:13px;border-top:1px solid #b6c2c9;margin-top:35px;padding-top:15px}@media(max-width:620px){main{padding:28px 16px}.metrics{grid-template-columns:1fr}.metrics strong{font-size:30px}table{font-size:12px}td,th{padding:8px 4px}td:nth-child(2){white-space:normal}}</style><main><p class="eyebrow">Raja Hasan · Independent launch measurement example · November 2026</p><h1>Did it grow?</h1><p class="intro">A new offer can win customers from your own product. The launch dashboard still looks great.</p><p class="notice"><strong>All data is simulated.</strong> Inspired by public consumer-finance product launches. No Intuit customer data, internal metrics, or claims about a real program. No model API or generated narrative is used at runtime.</p><nav aria-label="Choose a simulated scenario">'''
    for r in results:page+=f'<button data-scenario="{r["scenario"]}" aria-pressed="false">{html.escape(r["label"])}</button>'
    page+='</nav>'+''.join(cards)
    page+='''<div class="sensitivity"><h2>What would break this conclusion?</h2><label for="bias">Assume rollout markets had an unmeasured extra upward trend of <output id="bias-value">$0.00</output> per customer per week.</label><input id="bias" type="range" min="0" max="2" step="0.05" value="0"><p id="adjusted" aria-live="polite"></p><p>This is a simple bias calculation: subtract trend × 4.5 weeks from the estimate and interval. It is not a formal sensitivity bound, and does not resolve failed identification checks.</p></div><h2>The measurement choice</h2><p>Measure the offer’s availability across the entire eligible population. Keep existing-product revenue and service costs in the outcome. Never restrict the comparison to customers who chose to adopt.</p><h2>Where this stops</h2><p>Good pre-trends cannot rule out a new shock at launch. A national launch may have no unaffected donor markets. Cross-market spillovers, changed eligibility, or simultaneous pricing changes can make these estimates unusable. In that case, report the uncertainty and seek another design.</p><footer>Reproduce with <code>python analysis.py</code>. See README, SQL, methods, tests, and the analysis-error audit in the repository.</footer></main><script>const DATA=__DATA__;const dollars=x=>(x>=0?'+':'−')+'$'+Math.abs(x).toFixed(2);let active='migration';function update(){const r=DATA.find(x=>x.scenario===active),b=Number(document.getElementById('bias').value),shift=b*4.5;document.getElementById('bias-value').value='$'+b.toFixed(2);document.getElementById('adjusted').textContent='After this assumed bias: '+dollars(r.cohort_did-shift)+' contribution; shifted interval '+dollars(r.bootstrap_95_interval[0]-shift)+' to '+dollars(r.bootstrap_95_interval[1]-shift)+(r.identification_checks_pass?' .':' . Identification checks already fail; do not interpret this as a causal result.');}document.querySelectorAll('[data-scenario]').forEach(button=>button.addEventListener('click',()=>{active=button.dataset.scenario;document.querySelectorAll('.scenario').forEach(s=>s.classList.toggle('active',s.id===active));document.querySelectorAll('[data-scenario]').forEach(b=>b.setAttribute('aria-pressed',b===button));update();}));document.getElementById('bias').addEventListener('input',update);document.querySelector('[data-scenario="migration"]').click();</script></html>'''.replace('__DATA__',json.dumps([{k:r[k] for k in ['scenario','cohort_did','bootstrap_95_interval','identification_checks_pass']} for r in results]))
    (out/'index.html').write_text(page)
    # A static SVG preview works directly in a GitHub README.
    m=next(r for r in results if r['scenario']=='migration')
    preview=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="520" viewBox="0 0 1000 520"><rect width="1000" height="520" fill="#f5f5f0"/><g font-family="sans-serif" fill="#1c2c36"><text x="60" y="55" font-size="15">DID IT GROW? · SIMULATED DATA ONLY</text><text x="60" y="130" font-size="52" font-weight="700">A launch win. A business loss.</text><text x="60" y="183" font-size="22">New offer revenue rises. Existing revenue falls. Service costs remain.</text><path d="M60,225H940" stroke="#aab9bf"/><text x="60" y="270" font-size="17">New offer revenue</text><text x="375" y="270" font-size="17">Existing product revenue</text><text x="710" y="270" font-size="17">Business contribution</text><text x="60" y="335" font-size="54">{money(m['new_offer_lift'])}</text><text x="375" y="335" font-size="54">{money(m['existing_product_change'])}</text><text x="710" y="335" font-size="54" fill="#a14420">{money(m['cohort_did'])}</text><path d="M60,375H940" stroke="#aab9bf"/><text x="60" y="420" font-size="18">USD per baseline-eligible customer per week · cohort DiD vs never-treated markets</text><text x="60" y="463" font-size="17">SQL reporting + causal checks + one deliberately broken comparison</text><text x="60" y="493" font-size="13">Independent example by Raja Hasan. Not an estimate of Intuit performance.</text></g></svg>'''
    (out/'preview.svg').write_text(preview)
